begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','student_submissions','submission table exists');
select col_is_pk('public','student_submissions','id','UUID primary key');
select has_index('public','student_submissions','student_submissions_student_id_idx','student index');
select has_index('public','student_submissions','student_submissions_activity_student_key','activity student unique index');
select ok((select relrowsecurity from pg_class where oid='public.student_submissions'::regclass), 'RLS enabled');
select ok(has_table_privilege('authenticated','public.student_submissions','select'), 'read grant');
select ok(not has_table_privilege('authenticated','public.student_submissions','insert'), 'no direct insert');
select ok(not has_table_privilege('authenticated','public.student_submissions','update'), 'no direct update');
select ok(not has_table_privilege('authenticated','public.student_submissions','delete'), 'no direct delete');
select ok(not has_table_privilege('anon','public.student_submissions','select'), 'anonymous cannot read');
select ok(has_function_privilege('authenticated','public.save_student_activity_submission(uuid,text,text,text,boolean)','execute'), 'authenticated RPC');
select ok(not has_function_privilege('anon','public.save_student_activity_submission(uuid,text,text,text,boolean)','execute'), 'anonymous no RPC');
select ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.save_student_activity_submission(uuid,text,text,text,boolean)'::regprocedure), 'definer and empty search path');
insert into auth.users(id, email, raw_user_meta_data) values ('31000000-0000-4000-8000-000000000001','submission-1@example.test','{"display_name":"Submission fixture"}');
insert into auth.users(id, email, raw_user_meta_data) values ('31000000-0000-4000-8000-000000000002','submission-2@example.test','{"display_name":"Submission fixture"}');
insert into auth.users(id, email, raw_user_meta_data) values ('31000000-0000-4000-8000-000000000003','submission-3@example.test','{"display_name":"Submission fixture"}');
insert into auth.users(id, email, raw_user_meta_data) values ('31000000-0000-4000-8000-000000000004','submission-4@example.test','{"display_name":"Submission fixture"}');
update public.profiles set role='professor' where id in ('31000000-0000-4000-8000-000000000003','31000000-0000-4000-8000-000000000004');
insert into public.professor_applications(user_id,status,reviewed_at) values ('31000000-0000-4000-8000-000000000003','approved',now()),('31000000-0000-4000-8000-000000000004','approved',now()) on conflict(user_id) do update set status='approved',reviewed_at=now();
insert into public.workspaces(id,name,owner_id) values ('33000000-0000-4000-8000-000000000001','Submission testing','31000000-0000-4000-8000-000000000003');
insert into public.workspace_members(workspace_id,user_id,role) values ('33000000-0000-4000-8000-000000000001','31000000-0000-4000-8000-000000000001','student'),('33000000-0000-4000-8000-000000000001','31000000-0000-4000-8000-000000000002','student');
insert into public.xray_cases(id,workspace_id,storage_path,uploaded_by,mime_type,byte_size,upload_status,attested_by) values ('34000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001/34000000-0000-4000-8000-000000000001','31000000-0000-4000-8000-000000000003','image/png',100,'ready','31000000-0000-4000-8000-000000000003');
insert into public.activities(id,workspace_id,case_id,created_by,title,instructions) values ('32000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000001','31000000-0000-4000-8000-000000000003','Test activity 1','Review this chest X-ray.');
insert into public.activity_reference_evaluations(activity_id,evaluation) values ('32000000-0000-4000-8000-000000000001','Reference');
update public.activities set status='published' where id='32000000-0000-4000-8000-000000000001';
insert into public.xray_cases(id,workspace_id,storage_path,uploaded_by,mime_type,byte_size,upload_status,attested_by) values ('34000000-0000-4000-8000-000000000002','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001/34000000-0000-4000-8000-000000000002','31000000-0000-4000-8000-000000000003','image/png',100,'ready','31000000-0000-4000-8000-000000000003');
insert into public.activities(id,workspace_id,case_id,created_by,title,instructions) values ('32000000-0000-4000-8000-000000000002','33000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000002','31000000-0000-4000-8000-000000000003','Test activity 2','Review this chest X-ray.');
insert into public.activity_reference_evaluations(activity_id,evaluation) values ('32000000-0000-4000-8000-000000000002','Reference');
update public.activities set status='published' where id='32000000-0000-4000-8000-000000000002';
insert into public.xray_cases(id,workspace_id,storage_path,uploaded_by,mime_type,byte_size,upload_status,attested_by) values ('34000000-0000-4000-8000-000000000003','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001/34000000-0000-4000-8000-000000000003','31000000-0000-4000-8000-000000000003','image/png',100,'ready','31000000-0000-4000-8000-000000000003');
insert into public.activities(id,workspace_id,case_id,created_by,title,instructions) values ('32000000-0000-4000-8000-000000000003','33000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000003','31000000-0000-4000-8000-000000000003','Test activity 3','Review this chest X-ray.');
insert into public.activity_reference_evaluations(activity_id,evaluation) values ('32000000-0000-4000-8000-000000000003','Reference');
update public.activities set status='published' where id='32000000-0000-4000-8000-000000000003';
insert into public.xray_cases(id,workspace_id,storage_path,uploaded_by,mime_type,byte_size,upload_status,attested_by) values ('34000000-0000-4000-8000-000000000004','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001/34000000-0000-4000-8000-000000000004','31000000-0000-4000-8000-000000000003','image/png',100,'ready','31000000-0000-4000-8000-000000000003');
insert into public.activities(id,workspace_id,case_id,created_by,title,instructions) values ('32000000-0000-4000-8000-000000000004','33000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000004','31000000-0000-4000-8000-000000000003','Test activity 4','Review this chest X-ray.');
insert into public.activity_reference_evaluations(activity_id,evaluation) values ('32000000-0000-4000-8000-000000000004','Reference');
update public.activities set status='published' where id='32000000-0000-4000-8000-000000000004';
insert into public.xray_cases(id,workspace_id,storage_path,uploaded_by,mime_type,byte_size,upload_status,attested_by) values ('34000000-0000-4000-8000-000000000005','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001/34000000-0000-4000-8000-000000000005','31000000-0000-4000-8000-000000000003','image/png',100,'ready','31000000-0000-4000-8000-000000000003');
insert into public.activities(id,workspace_id,case_id,created_by,title,instructions) values ('32000000-0000-4000-8000-000000000005','33000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000005','31000000-0000-4000-8000-000000000003','Test activity 5','Review this chest X-ray.');
insert into public.activity_reference_evaluations(activity_id,evaluation) values ('32000000-0000-4000-8000-000000000005','Reference');
insert into public.xray_cases(id,workspace_id,storage_path,uploaded_by,mime_type,byte_size,upload_status,attested_by) values ('34000000-0000-4000-8000-000000000006','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000001/34000000-0000-4000-8000-000000000006','31000000-0000-4000-8000-000000000003','image/png',100,'ready','31000000-0000-4000-8000-000000000003');
insert into public.activities(id,workspace_id,case_id,created_by,title,instructions) values ('32000000-0000-4000-8000-000000000006','33000000-0000-4000-8000-000000000001','34000000-0000-4000-8000-000000000006','31000000-0000-4000-8000-000000000003','Test activity 6','Review this chest X-ray.');
insert into public.activity_reference_evaluations(activity_id,evaluation) values ('32000000-0000-4000-8000-000000000006','Reference');
update public.activities set status='published' where id='32000000-0000-4000-8000-000000000006';
update public.activities set due_at=clock_timestamp()-interval '1 second' where id='32000000-0000-4000-8000-000000000004';
update public.activities set status='archived' where id='32000000-0000-4000-8000-000000000006';
set local role authenticated;
select set_config('request.jwt.claim.sub','31000000-0000-4000-8000-000000000001',true);
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000001','  Findings  ','','',false), 'draft_saved', 'create partial draft');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000001','Updated findings','abnormal',' Left lung ',false), 'draft_saved', 'update draft');
select is((select count(*) from public.student_submissions),1::bigint,'repeated saves have one row');
select is((select relevant_region from public.student_submissions),'Left lung','RPC trims fields');
select is((select status from public.student_submissions),'draft','draft is not submitted');
select ok((select submitted_at is null from public.student_submissions),'draft has no submission time');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','','','',false), 'unavailable', 'empty draft denied');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','Findings','other','',false), 'unavailable', 'invalid classification');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002',repeat('x',5001),'normal','',false), 'unavailable', 'findings limit');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','Findings','abnormal',repeat('x',201),false), 'unavailable', 'region limit');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','','normal','',true), 'unavailable', 'final findings required');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','Findings','','',true), 'unavailable', 'final classification required');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','Findings','abnormal','',true), 'unavailable', 'abnormal region required');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000001','Final','abnormal','Left lung',true), 'submitted', 'finalize draft');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000001','Overwrite','normal','',false), 'already_submitted', 'final is immutable');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000001','Overwrite','normal','',true), 'already_submitted', 'duplicate final is idempotent');
select is((select visible_findings from public.student_submissions where activity_id='32000000-0000-4000-8000-000000000001'),'Final','final stays unchanged');
select ok((select submitted_at=updated_at and submitted_at>=created_at from public.student_submissions where activity_id='32000000-0000-4000-8000-000000000001'),'final timestamp valid');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','Clear','normal','discard',false), 'draft_saved', 'normal clears region');
select is((select relevant_region from public.student_submissions where activity_id='32000000-0000-4000-8000-000000000002'),'','normal has no region');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000004','Late','normal','',true), 'deadline_passed', 'database deadline enforced');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000005','Draft activity','normal','',false), 'unavailable', 'unpublished unavailable');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000006','Archived activity','normal','',false), 'unavailable', 'archived unavailable');
select set_config('request.jwt.claim.sub','31000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.student_submissions),0::bigint,'other student cannot see responses');
select set_config('request.jwt.claim.sub','31000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.student_submissions),1::bigint,'authorized professor sees only final');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000003','Professor','normal','',false), 'unauthorized', 'professor cannot submit');
select set_config('request.jwt.claim.sub','31000000-0000-4000-8000-000000000004',true);
select is((select count(*) from public.student_submissions),0::bigint,'unrelated professor sees nothing');
reset role;
update public.professor_applications set status='rejected',rejection_reason='Test revoke' where user_id='31000000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','31000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.student_submissions),0::bigint,'revoked professor cannot read finals');
reset role;
update public.activities set due_at=clock_timestamp()-interval '1 second' where id='32000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','31000000-0000-4000-8000-000000000001',true);
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000002','Late update','normal','',false), 'deadline_passed', 'expired draft cannot update');
select is((select status from public.student_submissions where activity_id='32000000-0000-4000-8000-000000000002'),'draft','expired draft stays unsubmitted');
reset role;
delete from public.workspace_members where workspace_id='33000000-0000-4000-8000-000000000001' and user_id='31000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*) from public.student_submissions),0::bigint,'former member cannot read own rows');
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000003','Nonmember','normal','',false), 'unauthorized', 'nonmember cannot submit');
select set_config('request.jwt.claim.sub','',true);
select is(public.save_student_activity_submission('32000000-0000-4000-8000-000000000003','Anonymous','normal','',false), 'unauthorized', 'missing identity denied');
reset role;
select throws_ok($$update public.student_submissions set visible_findings='Changed' where activity_id='32000000-0000-4000-8000-000000000001'$$,'42501','submission cannot be changed','immutable even through privileged update');
select throws_ok($$update public.student_submissions set status='other' where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'constraint rejects status');
select throws_ok($$update public.student_submissions set classification='other' where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'constraint rejects classification');
select throws_ok($$update public.student_submissions set visible_findings=repeat('x',5001) where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'constraint rejects visible_findings');
select throws_ok($$update public.student_submissions set relevant_region=repeat('x',201) where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'constraint rejects relevant_region');
select throws_ok($$update public.student_submissions set submitted_at=now() where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'constraint rejects submitted_at');
select throws_ok($$insert into public.student_submissions(activity_id,student_id,visible_findings) values ('32000000-0000-4000-8000-000000000002','31000000-0000-4000-8000-000000000001','duplicate')$$,'23505',null,'unique activity student constraint');
select throws_ok($$update public.student_submissions set visible_findings='  untrimmed  ' where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'findings must be trimmed');
select throws_ok($$update public.student_submissions set classification='abnormal', relevant_region='  left  ' where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'region must be trimmed');
select throws_ok($$update public.student_submissions set classification='normal', relevant_region='left' where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'normal region must be empty');
select throws_ok($$update public.student_submissions set status='submitted', visible_findings='', submitted_at=updated_at where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'final findings constraint');
select throws_ok($$update public.student_submissions set status='submitted', classification=null, submitted_at=updated_at where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'final classification constraint');
select throws_ok($$update public.student_submissions set status='submitted', classification='abnormal', relevant_region='', submitted_at=updated_at where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'final abnormal region constraint');
select throws_ok($$update public.student_submissions set status='submitted', submitted_at=null where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'final lifecycle constraint');
select throws_ok($$update public.student_submissions set updated_at=created_at-interval '1 second' where activity_id='32000000-0000-4000-8000-000000000002'$$,'23514',null,'timestamps ordered');
-- Anonymous execution is checked with has_function_privilege above. The local
-- Postgres image crashes on permission-denied RPC execution (also reproduced
-- against the pre-existing account-settings RPC), before returning SQLSTATE.
select * from finish();
rollback;
